/**
 * EventQueue — batched POST utility used by both:
 *
 *   - SOI-639 PLP web-vitals beacon → /internal/metrics/web-vitals
 *   - SOI-640 carousel events       → /api/v1/carousels/events
 *
 * Why a shared utility:
 *   - Both call sites need the same transport behaviour: batch a small number
 *     of events, flush via `sendBeacon` so they survive page navigation, fall
 *     back to `fetch({ keepalive: true })` when the body exceeds the 64 KB
 *     `sendBeacon` limit or when `sendBeacon` returns `false`.
 *   - Consent gating must be uniform — events emitted while consent is denied
 *     are dropped, never queued.
 *
 * Design notes:
 *   - Pure (no global side effects). Each call site instantiates its own queue.
 *   - No DOM access at construction time — `sendBeacon` is looked up via
 *     `getNavigator()` inside `flush()` so the module is import-safe in SSR /
 *     Worker contexts even though it ultimately requires a browser to actually
 *     deliver events.
 *   - `flushOnPageHide` is opt-in; the call site decides whether the queue
 *     should auto-flush on the `pagehide` event. PLP web-vitals = yes;
 *     carousel events on a long-lived SPA = also yes; tests = no.
 */

const SEND_BEACON_BODY_LIMIT_BYTES = 64 * 1024; // 64 KB per Web Beacon spec
const DEFAULT_DEBOUNCE_MS = 250;

export interface EventQueueOptions<TEvent> {
  /** Endpoint URL the batched POST hits. */
  endpoint: string;

  /**
   * Build the request body from the queued events. Most call sites will
   * `JSON.stringify({ ...envelope, events })` and return the resulting string.
   */
  serialize: (events: TEvent[]) => string;

  /**
   * Returns whether tracking consent is currently granted. Called every time
   * `enqueue()` runs; if it returns `false`, the event is dropped.
   */
  isConsentGranted: () => boolean;

  /** Debounce ms before an enqueue triggers a flush. Defaults to 250 ms. */
  debounceMs?: number;

  /**
   * Cap on the number of events held before a flush. When `enqueue()` would
   * push past this cap, the oldest event is dropped (FIFO). Defensive
   * insurance for pathological cases — long-lived SPA where consent toggles
   * rapidly, page hangs around for hours, etc. Unset = no cap.
   */
  maxQueueSize?: number;

  /**
   * Auto-flush on the `pagehide` window event. Defaults to `false` to keep
   * the constructor side-effect-free; PLP web-vitals + production carousel
   * code should pass `true`.
   */
  flushOnPageHide?: boolean;

  /**
   * Override `navigator` lookup — primarily for tests. In production the
   * default (window-bound) lookup is correct.
   */
  getNavigator?: () => Navigator | null;

  /**
   * Override `fetch` — primarily for tests. Defaults to `globalThis.fetch`.
   */
  getFetch?: () => typeof fetch;

  /**
   * Optional callback fired after every flush attempt (success or fallback).
   * Receives the number of events flushed and the transport that was used.
   * For SDK observability; OK to leave unset.
   */
  onFlush?: (info: { count: number; transport: 'beacon' | 'fetch' | 'dropped' }) => void;
}

export interface EventQueue<TEvent> {
  /** Add an event to the queue. Drops silently when consent is denied. */
  enqueue(event: TEvent): void;

  /**
   * Flush the queue immediately. Returns the transport that was used, or
   * `'noop'` when the queue was empty.
   */
  flush(): 'beacon' | 'fetch' | 'dropped' | 'noop';

  /** Number of events currently waiting. Useful for tests. */
  size(): number;

  /**
   * Tear down listeners, clear the pending timer, drop queued events.
   * Call sites should invoke this on container unmount.
   */
  destroy(): void;
}

/**
 * Build a fresh queue. The returned object is a closed-over scope; nothing
 * is shared between two `createEventQueue` calls.
 */
export function createEventQueue<TEvent>(options: EventQueueOptions<TEvent>): EventQueue<TEvent> {
  const {
    endpoint,
    serialize,
    isConsentGranted,
    debounceMs = DEFAULT_DEBOUNCE_MS,
    maxQueueSize,
    flushOnPageHide = false,
    getNavigator = () => (typeof navigator === 'undefined' ? null : navigator),
    getFetch = () => globalThis.fetch,
    onFlush,
  } = options;

  let pending: TEvent[] = [];
  let timerId: ReturnType<typeof setTimeout> | null = null;
  let destroyed = false;

  function clearTimer(): void {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
  }

  function scheduleFlush(): void {
    clearTimer();
    timerId = setTimeout(() => {
      timerId = null;
      flush();
    }, debounceMs);
  }

  function tryBeacon(body: string): boolean {
    const nav = getNavigator();
    if (!nav || typeof nav.sendBeacon !== 'function') return false;

    // Refuse sendBeacon when Blob is unavailable: without it we can't compute
    // an accurate byte length (`body.length` is UTF-16 code units, not bytes —
    // multi-byte UTF-8 characters undercount), and the 64 KB sendBeacon limit
    // is enforced byte-wise. The fetch keepalive fallback has no hard size
    // limit and handles non-browser environments correctly.
    if (typeof Blob === 'undefined') return false;

    // Wrap in a typed Blob so the browser sends `Content-Type: application/json`.
    // A bare string would default to `text/plain;charset=UTF-8`, which FastAPI
    // does not auto-parse as JSON — Pydantic then sees the raw string and rejects
    // the body with `model_attributes_type`. Triggers a CORS preflight (json is
    // not a safelisted Content-Type for beacons) so the endpoint must allow it.
    const blob = new Blob([body], { type: 'application/json' });
    if (blob.size > SEND_BEACON_BODY_LIMIT_BYTES) return false;

    try {
      // sendBeacon returns boolean: true = queued by browser, false = rejected.
      // Some browsers throw on cross-origin without proper CORS; treat that as false.
      return nav.sendBeacon(endpoint, blob);
    } catch {
      return false;
    }
  }

  function tryFetchKeepalive(body: string): boolean {
    const f = getFetch();
    if (typeof f !== 'function') return false;

    try {
      // Fire-and-forget. We don't await; keepalive ensures the request
      // survives unload. Errors are swallowed because there's no UI surface
      // to retry on. Returning `true` here means "queued for transport," NOT
      // "delivered to backend" — the `onFlush({ transport: 'fetch' })`
      // observability callback should be read with that contract in mind.
      void f(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body,
        keepalive: true,
      }).catch(() => undefined);
      return true;
    } catch {
      return false;
    }
  }

  function flush(): 'beacon' | 'fetch' | 'dropped' | 'noop' {
    clearTimer();

    if (pending.length === 0) return 'noop';

    const events = pending;
    pending = [];

    const body = serialize(events);

    let transport: 'beacon' | 'fetch' | 'dropped';

    if (tryBeacon(body)) {
      transport = 'beacon';
    } else if (tryFetchKeepalive(body)) {
      transport = 'fetch';
    } else {
      transport = 'dropped';
    }

    onFlush?.({ count: events.length, transport });
    return transport;
  }

  function enqueue(event: TEvent): void {
    if (destroyed) return;
    if (!isConsentGranted()) return;

    pending.push(event);
    // FIFO drop-oldest when the cap is set and we've crossed it. Keeps a
    // single misbehaving call site from blowing memory; the most recent event
    // (which is usually the one the user cares about) always survives.
    if (typeof maxQueueSize === 'number' && pending.length > maxQueueSize) {
      pending.splice(0, pending.length - maxQueueSize);
    }
    scheduleFlush();
  }

  function size(): number {
    return pending.length;
  }

  // pagehide handler captured so we can remove it on destroy.
  const pageHideHandler: ((this: Window, ev: PageTransitionEvent) => void) | null =
    flushOnPageHide && typeof window !== 'undefined' && typeof window.addEventListener === 'function'
      ? () => { flush(); }
      : null;

  if (pageHideHandler) {
    window.addEventListener('pagehide', pageHideHandler);
  }

  function destroy(): void {
    // Flush still-queued events before tearing down. React runs effect cleanups
    // in declaration order, so a consumer's own "safety flush" cleanup can run
    // *after* this destroy — without flushing here, the last ≤debounce-window of
    // events (and anything pending on a carouselId change) is silently dropped.
    flush();
    destroyed = true;
    clearTimer();
    pending = [];
    if (pageHideHandler && typeof window !== 'undefined') {
      window.removeEventListener('pagehide', pageHideHandler);
    }
  }

  return { enqueue, flush, size, destroy };
}
