/**
 * Structured price formatting with currency-display options.
 *
 * Why this exists: a single dollar sign (`$19.99`) is ambiguous on
 * multi-currency / international storefronts — Canadian / Australian users
 * may read it as their local dollar. We want to support all four common
 * conventions:
 *
 *   | style          | example     | use case                             |
 *   | -------------- | ----------- | ------------------------------------ |
 *   | `symbol`       | `$19.99`    | default; single-currency US stores   |
 *   | `code`         | `USD 19.99` | strictest disambiguation; technical  |
 *   | `symbol-code`  | `$19.99 USD`| friendly + unambiguous; media-style  |
 *   | `narrow`       | `US$19.99`  | locale-prefix, terse                 |
 *
 * The function returns separate `leadingCurrency` / `amount` /
 * `trailingCurrency` strings (rather than a single rendered string) so the
 * caller can wrap each in its own `<span>` for independent styling — e.g.
 * dimming the currency code or making the amount larger.
 *
 * Locale-aware via `Intl.NumberFormat` under the hood. Falls back to a
 * fixed-point string with the ISO code if Intl rejects the (locale,
 * currency) pair.
 *
 * ─── locale × style interaction (worth knowing) ─────────────────────────
 *   - `symbol` is locale-aware: USD in en-CA prefixes "US$", CAD in en-US
 *     prefixes "CA$" to disambiguate. For currencies without a Latin
 *     standalone symbol (PLN, JPY, SEK, etc.), Intl falls back to the ISO
 *     code prefix in non-native locales — e.g. PLN in en-US emits
 *     "PLN 99.99" automatically.
 *   - `narrow` strips the locale prefix: CAD in en-US becomes "$" — looks
 *     identical to USD. AVOID for multi-currency stores.
 *   - Number formatting (comma vs period decimal, group separator)
 *     follows the locale, not the style. `pl-PL` always uses comma decimal;
 *     `en-US` always uses period.
 *
 * The right combination depends on the audience:
 *   - single-currency store, local audience → `symbol`
 *   - multi-currency store, mixed audience → `code` or `symbol-code`
 *   - never `narrow` for multi-currency
 */

export type PriceFormatStyle =
  | 'symbol'        // $19.99       — Intl currencyDisplay: 'symbol'
  | 'code'          // USD 19.99    — Intl currencyDisplay: 'code'
  | 'symbol-code'   // $19.99 USD   — 'symbol' + ISO code suffix
  | 'narrow';       // US$19.99     — Intl currencyDisplay: 'narrowSymbol'

/**
 * Consumer-facing config: either a single style (applies to every currency)
 * or an object with a default + per-currency override map.
 *
 *   priceFormat: 'symbol'
 *   priceFormat: { default: 'symbol', byCurrency: { CAD: 'code', AUD: 'code' } }
 *
 * Per-currency keys are matched case-insensitively against the ISO 4217 code
 * the backend supplies on the item (e.g. price.currency = 'CAD').
 */
export type PriceFormatConfig =
  | PriceFormatStyle
  | { default?: PriceFormatStyle; byCurrency?: Readonly<Record<string, PriceFormatStyle>> };

/**
 * Resolve the effective style for a specific currency given the consumer's
 * config. Falls back to `'symbol'` when nothing matches.
 */
export function resolvePriceFormat(
  currency: string,
  config: PriceFormatConfig | undefined,
): PriceFormatStyle {
  if (!config) return 'symbol';
  if (typeof config === 'string') return config;
  if (config.byCurrency) {
    const override = config.byCurrency[currency.toUpperCase()];
    if (override) return override;
  }
  return config.default ?? 'symbol';
}

export interface PriceParts {
  /** Currency string to render before the amount (with any trailing space). Null when the style places currency after. */
  leadingCurrency: string | null;
  /** Numeric portion, e.g. "19.99". Always present. */
  amount: string;
  /** Currency string to render after the amount (with any leading space). Null when the style places currency before. */
  trailingCurrency: string | null;
}

const FALLBACK_FRACTION_DIGITS = 2;

/**
 * Format a numeric price into structured currency + amount parts.
 *
 * @param value     Numeric price. Non-finite values yield `null`.
 * @param currency  ISO 4217 code (e.g. 'USD', 'EUR', 'GBP', 'CAD').
 * @param locale    BCP-47 locale tag. Defaults to 'en-US'.
 * @param style     Which currency-display convention to use. Defaults to 'symbol'.
 */
export function formatPriceParts(
  value: number,
  currency: string,
  locale: string = 'en-US',
  style: PriceFormatStyle = 'symbol',
): PriceParts | null {
  if (!Number.isFinite(value)) return null;

  // Map our style to Intl's currencyDisplay option. 'symbol-code' has no
  // direct Intl equivalent — we format with 'symbol' display and append the
  // ISO code manually as a trailing tag.
  const intlDisplay: 'symbol' | 'code' | 'narrowSymbol' =
    style === 'code' ? 'code' : style === 'narrow' ? 'narrowSymbol' : 'symbol';

  let parts: Intl.NumberFormatPart[];
  try {
    parts = new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      currencyDisplay: intlDisplay,
    }).formatToParts(value);
  } catch {
    // Unknown currency / locale combination — fall back to a plain string
    // with the ISO code prefix so we at least show the right denomination.
    return {
      leadingCurrency: currency + ' ',
      amount: value.toFixed(FALLBACK_FRACTION_DIGITS),
      trailingCurrency: null,
    };
  }

  // Walk the parts and partition: everything before the numeric block goes
  // into `leading`, the numeric block into `amount`, and anything after
  // (including its preceding separator) into `trailing`.
  let leading = '';
  let amount = '';
  let trailingBuffer = '';
  let trailing = '';
  let sawAmount = false;

  for (const part of parts) {
    if (part.type === 'currency') {
      if (sawAmount) {
        // Flush any buffered post-amount separator before the trailing currency.
        trailing += trailingBuffer + part.value;
        trailingBuffer = '';
      } else {
        leading += part.value;
      }
    } else if (part.type === 'literal') {
      if (!sawAmount) {
        // Whitespace between leading currency and the number — keep with the
        // leading chunk so consumers can wrap "USD " (with trailing space) in
        // one span.
        leading += part.value;
      } else {
        // Whitespace after the number. Don't commit yet — only meaningful
        // if a trailing currency follows.
        trailingBuffer += part.value;
      }
    } else {
      // integer / group / decimal / fraction — all part of the numeric amount.
      amount += part.value;
      sawAmount = true;
    }
  }

  // 'symbol-code' synthesises the trailing ISO code. Always renders with a
  // space separator regardless of locale (the locale already drew the
  // leading symbol; the trailing code is our own addition).
  if (style === 'symbol-code') {
    trailing = ' ' + currency;
  }

  return {
    leadingCurrency: leading.length > 0 ? leading : null,
    amount,
    trailingCurrency: trailing.length > 0 ? trailing : null,
  };
}
